//! Settings screen: video quality, smoothness, output folder, assistant.

use std::path::PathBuf;

use eframe::egui::{self, Color32, RichText};

use crate::settings::{Fps, LanguageChoice, QualityPreset, Settings};
use crate::shortcut::{Shortcut, ShortcutProblem};
use crate::texts::{self, settings as t};

/// Generated by `scripts/third-party-licenses.ps1` (CI checks it is up to
/// date); embedded so the About section never depends on an installed file.
const THIRD_PARTY_LICENSES: &str = include_str!("../../../../THIRD_PARTY_LICENSES.md");

#[derive(Debug, PartialEq, Eq)]
pub enum SettingsAction {
    /// Quality, smoothness or sound changed (already written into the
    /// settings): the preview restarts with them.
    VideoChanged,
    PickFolder,
    OpenFolder(PathBuf),
    OpenAssistant,
    /// Pair a phone over Wi-Fi.
    OpenWireless,
    /// A setting without other effect changed: just save.
    Save,
    /// The instant replay changed: applied to the preview without restarting
    /// it (what is kept stays).
    ReplayChanged,
    OpenLicenses,
    /// The interface language changed (already written into the settings).
    LanguageChanged,
}

/// Draws the settings; edits `settings` in place.
pub fn show(
    ui: &mut egui::Ui,
    settings: &mut Settings,
    picking_folder: bool,
    editor: &mut ShortcutEditor,
) -> Vec<SettingsAction> {
    let mut actions = Vec::new();
    egui::CentralPanel::default().show(ui, |ui| {
        egui::ScrollArea::vertical().show(ui, |ui| {
            ui.heading(RichText::new(t::title()).size(24.0));
            ui.add_space(12.0);

            section(ui, t::language_title());
            for choice in [
                LanguageChoice::Auto,
                LanguageChoice::French,
                LanguageChoice::English,
            ] {
                let label = RichText::new(t::language_choice(choice)).size(16.0);
                if ui
                    .radio_value(&mut settings.language, choice, label)
                    .changed()
                {
                    actions.push(SettingsAction::LanguageChanged);
                }
            }
            ui.add_space(12.0);

            section(ui, t::quality());
            for preset in [
                QualityPreset::Light,
                QualityPreset::Standard,
                QualityPreset::High,
            ] {
                let (name, hint) = t::quality_preset(preset);
                if choice(ui, &mut settings.quality, preset, name, hint) {
                    actions.push(SettingsAction::VideoChanged);
                }
            }
            ui.add_space(12.0);

            section(ui, t::fps());
            for fps in [Fps::Thirty, Fps::Sixty] {
                let (name, hint) = t::fps_choice(fps);
                if choice(ui, &mut settings.fps, fps, name, hint) {
                    actions.push(SettingsAction::VideoChanged);
                }
            }
            ui.label(RichText::new(t::applies_now()).small());
            ui.add_space(16.0);

            section(ui, t::sound());
            let record = RichText::new(t::record_sound()).size(16.0);
            if ui.checkbox(&mut settings.record_sound, record).changed() {
                actions.push(SettingsAction::VideoChanged);
            }
            ui.indent("record-sound", |ui| {
                ui.label(RichText::new(t::record_sound_hint()).weak());
            });
            let listen = RichText::new(t::listen_sound()).size(16.0);
            if ui
                .add_enabled(
                    settings.record_sound,
                    egui::Checkbox::new(&mut settings.listen_sound, listen),
                )
                .changed()
            {
                actions.push(SettingsAction::VideoChanged);
            }
            ui.indent("listen-sound", |ui| {
                ui.label(RichText::new(t::listen_sound_hint()).weak());
            });
            ui.add_space(16.0);

            section(ui, t::folder());
            ui.horizontal(|ui| {
                ui.monospace(settings.output_dir.display().to_string());
            });
            ui.horizontal(|ui| {
                if ui.button(texts::open_folder()).clicked() {
                    actions.push(SettingsAction::OpenFolder(settings.output_dir.clone()));
                }
                if ui
                    .add_enabled(!picking_folder, egui::Button::new(texts::folder_change()))
                    .clicked()
                {
                    actions.push(SettingsAction::PickFolder);
                }
            });
            ui.add_space(16.0);

            section(ui, t::assistant());
            if ui
                .button(RichText::new(t::assistant_button()).size(16.0))
                .clicked()
            {
                actions.push(SettingsAction::OpenAssistant);
            }
            ui.add_space(16.0);

            section(ui, t::replay_title());
            let label = RichText::new(t::replay_enabled()).size(16.0);
            if ui.checkbox(&mut settings.replay_enabled, label).changed() {
                actions.push(SettingsAction::ReplayChanged);
            }
            ui.add_enabled_ui(settings.replay_enabled, |ui| {
                ui.horizontal(|ui| {
                    for seconds in [15, 30, 60, 120] {
                        let text = RichText::new(t::replay_length(seconds)).size(16.0);
                        if ui
                            .radio_value(&mut settings.replay_seconds, seconds, text)
                            .changed()
                        {
                            actions.push(SettingsAction::ReplayChanged);
                        }
                    }
                });
            });
            ui.indent("replay-hint", |ui| {
                ui.label(RichText::new(t::replay_hint()).weak());
            });
            ui.add_space(16.0);

            section(ui, t::shortcut_title());
            let other = settings.replay_shortcut.clone();
            if editor.show(ui, ShortcutTarget::Cut, &mut settings.cut_shortcut, &other) {
                actions.push(SettingsAction::Save);
            }
            let other = settings.cut_shortcut.clone();
            if editor.show(
                ui,
                ShortcutTarget::Replay,
                &mut settings.replay_shortcut,
                &other,
            ) {
                actions.push(SettingsAction::Save);
            }
            ui.label(RichText::new(t::shortcut_hint()).weak());
            ui.add_space(16.0);

            section(ui, t::updates());
            let label = RichText::new(t::check_updates()).size(16.0);
            if ui.checkbox(&mut settings.check_updates, label).changed() {
                actions.push(SettingsAction::Save);
            }
            ui.indent("check-updates", |ui| {
                ui.label(RichText::new(t::check_updates_hint()).weak());
            });
            ui.add_space(16.0);

            section(ui, texts::wireless::title());
            ui.label(RichText::new(texts::wireless::intro()).weak());
            if ui
                .button(RichText::new(texts::wireless::open_button()).size(16.0))
                .clicked()
            {
                actions.push(SettingsAction::OpenWireless);
            }
            ui.add_space(16.0);

            section(ui, t::about());
            ui.label(RichText::new(t::version(env!("CARGO_PKG_VERSION"))).strong());
            ui.add_space(4.0);
            ui.label(t::about_uses());
            for credit in t::about_credits() {
                ui.add(egui::Label::new(format!("•  {credit}")).wrap());
            }
            ui.add_space(4.0);
            egui::CollapsingHeader::new(t::third_party_licenses())
                .id_salt("third-party-licenses")
                .show(ui, |ui| {
                    egui::ScrollArea::vertical()
                        .id_salt("third-party-licenses-text")
                        .max_height(320.0)
                        .show(ui, |ui| {
                            ui.add(
                                egui::Label::new(RichText::new(THIRD_PARTY_LICENSES).monospace())
                                    .wrap(),
                            );
                        });
                });
            if ui.button(t::open_licenses()).clicked() {
                actions.push(SettingsAction::OpenLicenses);
            }
            ui.add_space(8.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new(texts::support_after_export()).weak());
                ui.hyperlink_to(texts::support_project(), texts::support_url());
            });
        });
    });
    actions
}

/// Changing the "mark a cut" shortcut: waits for the next combination and
/// keeps it only if it is allowed (see [`Shortcut::from_keys`]).
/// Which shortcut is being changed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ShortcutTarget {
    Cut,
    Replay,
}

#[derive(Default)]
pub struct ShortcutEditor {
    capturing: Option<ShortcutTarget>,
    problem: Option<(ShortcutTarget, ShortcutProblem)>,
}

impl ShortcutEditor {
    /// While capturing, the shortcuts must not fire.
    pub fn is_capturing(&self) -> bool {
        self.capturing.is_some()
    }

    /// Returns `true` when the shortcut changed (to save).
    fn show(
        &mut self,
        ui: &mut egui::Ui,
        target: ShortcutTarget,
        shortcut: &mut Shortcut,
        other: &Shortcut,
    ) -> bool {
        let default = match target {
            ShortcutTarget::Cut => Shortcut::default(),
            ShortcutTarget::Replay => Shortcut::replay_default(),
        };
        let capturing = self.capturing == Some(target);
        let mut changed = false;
        ui.horizontal(|ui| {
            ui.label(
                RichText::new(match target {
                    ShortcutTarget::Cut => t::shortcut_cut(),
                    ShortcutTarget::Replay => t::shortcut_replay(),
                })
                .size(16.0),
            );
            ui.label(
                RichText::new(shortcut.label())
                    .size(16.0)
                    .strong()
                    .monospace(),
            );
            if capturing {
                ui.label(RichText::new(t::shortcut_press()).color(Color32::from_rgb(77, 145, 230)));
            } else if self.capturing.is_none() {
                if ui.button(t::shortcut_change()).clicked() {
                    self.capturing = Some(target);
                    self.problem = None;
                }
                if *shortcut != default
                    && default != *other
                    && ui.button(t::shortcut_reset()).clicked()
                {
                    *shortcut = default.clone();
                    self.problem = None;
                    changed = true;
                }
            }
        });
        if capturing {
            let pressed = ui.input(|i| {
                i.events.iter().find_map(|event| match event {
                    egui::Event::Key {
                        key,
                        pressed: true,
                        modifiers,
                        ..
                    } => Some((*key, *modifiers)),
                    _ => None,
                })
            });
            if let Some((key, modifiers)) = pressed {
                if key == egui::Key::Escape && !modifiers.any() {
                    self.capturing = None;
                } else {
                    match Shortcut::from_keys(key, modifiers) {
                        Ok(new) if new == *other => {
                            self.problem = Some((target, ShortcutProblem::InUse));
                        }
                        Ok(new) => {
                            *shortcut = new;
                            self.capturing = None;
                            self.problem = None;
                            changed = true;
                        }
                        Err(problem) => self.problem = Some((target, problem)),
                    }
                }
            }
        }
        if let Some((problem_target, problem)) = self.problem {
            if problem_target == target {
                ui.colored_label(Color32::from_rgb(214, 120, 0), t::shortcut_problem(problem));
            }
        }
        changed
    }
}

fn section(ui: &mut egui::Ui, title: &str) {
    ui.label(RichText::new(title).size(18.0).strong());
    ui.add_space(4.0);
}

/// A radio button with an explanation below. Returns `true` when changed.
fn choice<T: PartialEq + Copy>(
    ui: &mut egui::Ui,
    current: &mut T,
    value: T,
    name: &str,
    hint: &str,
) -> bool {
    let changed = ui
        .radio_value(current, value, RichText::new(name).size(16.0))
        .changed();
    ui.indent(name, |ui| {
        ui.label(RichText::new(hint).weak());
    });
    ui.add_space(2.0);
    changed
}
